       ("q127b", "Alternativa B: linhas retas atravessando o anel, mas com sentido de B para A."),
       ("q127c", "Alternativa C: linhas de B para A que se curvam em torno do anel, sem entrar nele."),
       ("q127d", "Alternativa D: linhas de A para B que se curvam e se cruzam dentro do anel."),
